"""Build the official app homepage from the existing GAYBOY page and assets."""
from pathlib import Path
import json
import shutil
from html.parser import HTMLParser

ROOT=Path(__file__).resolve().parents[1]
DEST=ROOT/'network/apps/gayboy'
DEST.mkdir(parents=True,exist_ok=True)
for name in ['emulator/player.css','emulator/player.js','emulator/tutorial.js','emulator/tutorial-rom.json','emulator/sameboy.js','emulator/sameboy.wasm','emulator/SAMEBOY-LICENSE.txt','emulator/SAMEBOY-UPSTREAM.txt','downloads/GAYBOY-0.3.gb','downloads/GAYBOY-tutorial.gb','downloads/SHA256SUMS.txt','images/train.png','images/turntable.png','images/drum-machine.png','images/sequencer.png','images/mixer.png']:
    path=DEST/name;path.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(ROOT/'website'/name,path)
source=(ROOT/'website/index.html').read_text(encoding='utf-8')
start=source.index('        <section id="live-demo"')
end=source.index('        <section class="status-box"',start)
player='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>GAYBOY — Y2KCRISIS app</title><link rel="stylesheet" href="emulator/player.css"><link rel="stylesheet" href="player-shell.css"><script src="emulator/tutorial.js" defer></script><script src="emulator/player.js" defer></script><script src="network-beats.js" defer></script></head><body>'''+source[start:end]+'''</body></html>'''
(DEST/'player.html').write_text(player,encoding='utf-8')
(DEST/'player-shell.css').write_text('''body{margin:0;padding:12px;color:#fff0ff;background:#210331;font:13px/1.5 Verdana,sans-serif}*{box-sizing:border-box}a{color:#88f9ff}button{cursor:pointer}#live-demo{max-width:700px;margin:auto}.panel-content{padding:4px}.demo-intro{text-align:center;color:#ff81d9}kbd{background:#190029;padding:3px}.demo-credit{font-size:10px}''',encoding='utf-8')
(DEST/'.htaccess').write_text('''<IfModule mod_headers.c>
Header always set Content-Security-Policy "default-src 'self'; script-src 'self' 'wasm-unsafe-eval'; style-src 'self'; img-src 'self' data:; object-src 'none'; base-uri 'self'; frame-ancestors 'self'"
</IfModule>
AddType application/wasm .wasm
''',encoding='utf-8')
