(DEST/'player-shell.css').write_text((DEST/'player-shell.css').read_text(encoding='utf-8')+'''\n.beat-shelf{max-width:700px;margin:25px auto;border:2px solid #ff81d9;padding:16px}.beat-shelf article{border-top:1px dashed #a86caf;padding:14px 0}.beat-shelf button,.network-beat-dialog button{background:#d5ff39;color:#190029;padding:9px;border:2px outset #ddd;cursor:pointer}.beat-shelf article p{font-size:11px}.beat-shelf a{font-size:11px;margin-right:12px}.network-beat-dialog{max-width:90vw;width:400px;background:#210331;color:#fff0ff;border:3px ridge #ff81d9}.network-beat-dialog label{display:block;margin:15px 0}.network-beat-dialog input{width:100%;padding:10px}.network-beat-dialog p{font-size:12px}''',encoding='utf-8')
